// --- Hand-written helpers over the extracted tables. ---

/// Chroma QP from the luma QP (Table 8-10 with its out-of-range rules).
pub fn qpc(qpi: u8) -> u8 {
    if qpi < 30 {
        qpi
    } else if qpi <= 43 {
        QPC_30_43[(qpi - 30) as usize]
    } else {
        qpi - 6
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dct_matrix_shape_and_dc_basis() {
        // Row 0 is the DC basis; every row norm clusters at 32 * 64^2 with the
        // small integer-rounding spread of the spec matrix (observed 130960..131244).
        assert_eq!(TRANS_MATRIX[0], [64; 32]);
        for (i, row) in TRANS_MATRIX.iter().enumerate() {
            let n = row.iter().map(|&v| (v as i32) * (v as i32)).sum::<i32>();
            assert!((n - 131072).abs() <= 256, "row {i}: norm {n}");
        }
    }

    #[test]
    fn intra_angles_have_the_spec_shape() {
        assert_eq!(INTRA_PRED_ANGLE[10], 0);
        assert_eq!(INTRA_PRED_ANGLE[26], 0);
        for m in 2..=34 {
            assert!((-32..=32).contains(&INTRA_PRED_ANGLE[m]), "mode {m}");
            assert_eq!(INTRA_PRED_ANGLE[m], INTRA_PRED_ANGLE[36 - m], "symmetric pair {m}");
        }
        assert!(INTRA_PRED_ANGLE[2..=10].windows(2).all(|w| w[0] >= w[1]));
        assert!(INTRA_PRED_ANGLE[18..=26].windows(2).all(|w| w[0] <= w[1]));
        assert_eq!(INV_ANGLE.len(), 15);
        assert_eq!(INV_ANGLE[7], -256);
        assert!(INV_ANGLE.windows(2).take(7).all(|w| w[0] <= w[1]));
        assert!(INV_ANGLE.windows(2).skip(7).all(|w| w[0] >= w[1]));
    }

    #[test]
    fn chroma_qp_mapping_boundaries() {
        assert_eq!(qpc(0), 0);
        assert_eq!(qpc(29), 29);
        assert_eq!(qpc(30), 29);
        assert_eq!(qpc(43), 37);
        assert_eq!(qpc(44), 38);
        assert_eq!(qpc(51), 45);
    }

    #[test]
    fn cabac_layout_shape() {
        assert_eq!(NUM_CTX, 163);
        assert_eq!(SPLIT_CU, 2);
        assert_eq!(LAST_X_PREFIX + 18, LAST_Y_PREFIX);
        for row in &CABAC_INIT {
            assert_eq!(row.len(), NUM_CTX);
        }
        // Unused initType slots carry the 154 filler.
        assert_eq!(CABAC_INIT[0][CU_SKIP], 154);
        // Spot anchors read first-hand from Tables 9-5..9-7 (initValue is an 8-bit
        // entry, so values above 154 are genuine: Table 9-6 is 200/185/160).
        assert_eq!(CABAC_INIT[0][SAO_MERGE], 153);
        assert_eq!(CABAC_INIT[1][SAO_TYPE], 185);
        assert_eq!(CABAC_INIT[1][SPLIT_CU], 107);
        assert_eq!(CABAC_INIT[2][SPLIT_CU + 2], 126);
    }

    #[test]
    fn interpolation_filters_sum_to_64() {
        assert_eq!(LUMA_FILTER[0], [0, 0, 0, 64, 0, 0, 0, 0]);
        for taps in &LUMA_FILTER {
            assert_eq!(taps.iter().map(|&v| v as i32).sum::<i32>(), 64);
        }
        assert_eq!(CHROMA_FILTER[0], [0, 64, 0, 0]);
        for taps in &CHROMA_FILTER {
            assert_eq!(taps.iter().map(|&v| v as i32).sum::<i32>(), 64);
        }
    }

    #[test]
    fn levels_main_shape_and_spot_values() {
        assert_eq!(LEVELS_MAIN.len(), 13);
        assert!(LEVELS_MAIN.windows(2).all(|w| w[0].0 < w[1].0));
        let l4 = LEVELS_MAIN.iter().find(|&&(idc, ..)| idc == 120).unwrap();
        assert_eq!(*l4, (120, 2228224, 66846720, 12000, 12000));
    }
}
